  + ".sd25-header p { margin: 0; font-size: 12px; opacity: 0.7; }\n"
  + ".sd25-body { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n"
  + ".sd25-left, .sd25-right { background: var(--card, rgba(255,255,255,0.03)); border: 1px solid var(--border, rgba(255,255,255,0.08)); border-radius: 8px; padding: 12px; min-height: 320px; max-height: 70vh; overflow-y: auto; }\n"
  + ".sd25-toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; margin-bottom: 10px; }\n"
  + ".sd25-toolbar-group { display: flex; flex-direction: column; gap: 4px; font-size: 11px; opacity: 0.8; }\n"
