  + ".sd25-field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 8px; font-size: 12px; }\n"
  + ".sd25-label { font-weight: 500; opacity: 0.85; }\n"
  + ".sd25-input, .sd25-textarea { background: var(--input, rgba(0,0,0,0.2)); color: inherit; border: 1px solid var(--border, rgba(255,255,255,0.15)); border-radius: 4px; padding: 6px 8px; font-size: 12px; font-family: inherit; width: 100%; box-sizing: border-box; }\n"
  + ".sd25-textarea { resize: vertical; min-height: 40px; }\n"
  + ".sd25-small { width: 60px; }\n"
  + ".sd25-flex { flex: 1; }\n"
  + ".sd25-section { margin: 12px 0; }\n"
  + ".sd25-section-title { font-size: 12px; font-weight: 600; margin-bottom: 6px; opacity: 0.9; }\n"
