  + ".sd25-btn { background: var(--btn, rgba(255,255,255,0.08)); color: inherit; border: 1px solid var(--border, rgba(255,255,255,0.15)); border-radius: 4px; padding: 6px 12px; font-size: 12px; cursor: pointer; }\n"
