  + ".sd25-btn-primary:hover:not(:disabled) { filter: brightness(1.1); }\n"
  + ".sd25-btn-sm { padding: 4px 8px; font-size: 11px; }\n"
  + ".sd25-btn-text { background: transparent; color: inherit; border: none; cursor: pointer; font-size: 12px; padding: 4px 0; opacity: 0.7; }\n"
  + ".sd25-btn-text:hover { opacity: 1; }\n"
  + ".sd25-btn-icon { background: transparent; color: inherit; border: 1px solid var(--border, rgba(255,255,255,0.15)); border-radius: 4px; padding: 0 6px; cursor: pointer; opacity: 0.7; }\n"
  + ".sd25-btn-icon:hover { opacity: 1; background: rgba(255,255,255,0.1); }\n"
  + ".sd25-info { font-size: 11px; opacity: 0.7; margin-bottom: 12px; padding: 6px 8px; background: rgba(255,255,255,0.03); border-radius: 4px; }\n"
  + ".sd25-details { font-size: 12px; margin-bottom: 8px; }\n"
