  + ".sd25-pre { background: rgba(0,0,0,0.3); border: 1px solid var(--border, rgba(255,255,255,0.08)); border-radius: 4px; padding: 10px; font-size: 12px; line-height: 1.6; white-space: pre-wrap; word-break: break-word; max-height: 50vh; overflow-y: auto; margin: 0; font-family: ui-monospace, \"SF Mono\", Menlo, monospace; }\n"
